:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-panel: #f8f8f8;
  --color-quartz-well: #ededed;
  --color-linen-banner: #f8f9f5;
  --color-carbon-footer: #151515;
  --color-ink: #1b1b1e;
  --color-indigo-ink: #090b2b;
  --color-steel-caption: #808080;
  --color-pewter-meta: #8c8c8c;
  --color-ash-footer: #aaaaaa;
  --color-dove-border: #d7d7d7;
  --color-mist-hairline: #e5e5e5;
  --color-sage-signal: #e5ebd3;

  /* Typography — Font Families */
  --font-flatfile-diatype: "FlatfileDiatype", "FlatfileDiatypeVariable", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-source-serif-4: "Source Serif 4", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-sharp-grotesk: "Sharp Grotesk", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-caption: 12px;
  --leading-caption: 1.42;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: -0.25px;
  --text-subheading: 22px;
  --leading-subheading: 1.18;
  --tracking-subheading: -0.5px;
  --text-heading: 26px;
  --leading-heading: 1.42;
  --tracking-heading: -0.26px;
  --text-heading-lg: 38px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -1.2px;
  --text-display: 60px;
  --leading-display: 1;
  --tracking-display: -1.8px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-9: 9px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-56: 56px;
  --spacing-64: 64px;
  --spacing-72: 72px;
  --spacing-88: 88px;
  --spacing-120: 120px;

  /* Layout */
  --layout-page-max-width: 1168px;
  --layout-section-gap: 120px;
  --layout-card-padding: 24px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-full: 99px;
  --radius-full-2: 100px;
  --radius-full-3: 999px;

  /* Named Radii */
  --radius-buttons: 99px;
  --radius-nav: 999px;
  --radius-small-elements: 100px;
  --radius-alert-banners: 12px;
  --radius-small-cards: 8px;
  --radius-avatars: 50%;
  --radius-cards: 0px;
  --radius-images: 0px;
  --radius-sections: 0px;

  /* Shadows */
  --shadow-subtle: inset 0px 8px 12px -8px rgba(0, 0, 0, 0.1), inset 0px -8px 12px -4px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0px 20px 34px 0px rgba(0, 0, 0, 0.11), 0px 13px 21px 0px rgba(0, 0, 0, 0.09), 0px 8px 13px 0px rgba(0, 0, 0, 0.08), 0px 5px 8px 0px rgba(0, 0, 0, 0.07), 0px 3px 4px 0px rgba(0, 0, 0, 0.05), 0px 1px 2px 0px rgba(0, 0, 0, 0.04);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-panel: #f8f8f8;
  --surface-quartz-well: #ededed;
  --surface-carbon-footer: #151515;
}

